let ladderExpanded=false;
function rungExplanation(a,b){
 const e=M.comparison(graph,a.name,b.name);let title,story,details='';
 if(e.kind==='direct'){
  const winner=e.delta>=0?a:b,loser=e.delta>=0?b:a;title=e.direction==='supports'?'The last meeting supports this step':e.direction==='opposes'?'The last meeting points the other way':'Level at their last meeting';story=e.delta===0?'They recorded level margins.':`${winner.display} finished ${fmt(Math.abs(e.delta))}L ahead of ${loser.display}.`;
  details=`<p>${esc(e.latest.race.track)} · ${shortDate(e.latest.race.date)} · ${e.latest.race.distance}m</p>${e.reversal?'<p>They have traded places before.</p>':''}${e.direction==='opposes'?`<p>Other available matchups still put ${esc(a.display)} above overall.</p>`:''}`;
 }else if(e.kind==='indirect'){
  title='A shared-rival clue';story=e.commonRival?`Both raced ${display(e.commonRival)} in separate races. ${e.direction==='supports'?'The margins support this order.':'That comparison does not clearly support this order.'}`:`A ${e.steps.length}-race chain connects them; it is not a direct meeting.`;
  details=e.steps.map(s=>`<p>${esc(display(s.delta>=0?s.from:s.to))} ${s.delta===0?'level with':`${fmt(Math.abs(s.delta))}L ahead of`} ${esc(display(s.delta>=0?s.to:s.from))}<small>${esc(s.edge.race.track)} · ${shortDate(s.edge.race.date)}</small></p>`).join('')+'<p>Different races are a clue, not a predicted winning margin.</p>';
 }else{title='Not enough shared history';story='No short shared-race path supports this comparison. Their relative position is uncertain.'}
 return `<div class="rung-explanation ${e.direction==='supports'?'supported':'uncertain'}"><span class="rung-caption">WHY ABOVE ${esc(b.display.toUpperCase())}?</span><h4>${esc(title)}</h4><p>${esc(story)}</p>${details?`<details class="rung-detail"><summary>See the races <span>+</span></summary>${details}<a href="${esc(race.source)}" target="_blank" rel="noopener">Published history ↗</a></details>`:''}</div>`;
}
function renderLadder(){if(!race)return;const field=active(),shown=ladderExpanded?field:field.slice(0,4);document.getElementById('ladderStatus').textContent='Original form order · shared races are evidence, not proof.';document.getElementById('formLadder').innerHTML=shown.map((h,i)=>`<article class="ladder-rung"><div class="ladder-horse"><span class="ladder-position">${i+1}</span>${silk(h,'large')}<div><h3>${esc(h.display)}</h3><p>No. ${h.number}</p></div><button data-ladder-horse="${esc(h.name)}" aria-label="View ${esc(h.display)}">↗</button></div>${i<shown.length-1?rungExplanation(h,shown[i+1]):''}</article>`).join('');document.querySelectorAll('[data-ladder-horse]').forEach(b=>b.onclick=()=>inspectRunner(b.dataset.ladderHorse));const show=document.getElementById('showFullLadder');show.hidden=field.length<=4;show.textContent=ladderExpanded?'Show the leading four ↑':`See all ${field.length} runners ↓`;show.setAttribute('aria-expanded',String(ladderExpanded))}
document.getElementById('showFullLadder').onclick=()=>{ladderExpanded=!ladderExpanded;renderLadder()};
